exec('uec_param id=1 reordering_window_size=1000 reordering_timer=200') 
exec('uec_param id=2 reordering_window_size=1000 reordering_timer=200') 

-----Cipher offload flag to distribute:ciphering=uec/distributed-----

exec('sim_param_set NR_PDCP_CIPHERING=skip PDCP_DECRYPTION=distributed NR_PDCP_INTEGRITY_PROTECTION=skip') 
---PDCP header (4 bytes) + IPv4 Header (20 bytes) + UDP header (8 bytes) + SimMode Header (7 bytes) = 39 bytes
---PDCP header (4 bytes) + IPv4 Header (20 bytes) + RTP header (12 bytes) + SimMode Header (7 bytes) = 43 bytes
---PDCP header (4 bytes) + IPv4 Header (20 bytes) + TCP header (20 bytes) + SimMode Header (7 bytes) = 51 bytes
exec('sim_param_set NR_PDCP_TRUNCATE_DL_SIZE=55') 
exec('sim_param_set NR_PDCP_BUNDLE_DL_MAX_SIZE=8960') 
exec('sim_param_set NR_PDCP_BUNDLE_DL_TIMEOUT=500') 

exec('debug_log level=5') 
exec('sim_debug_log level=4 uec=1-2') 
exec('link_ctrl_param use_hb=off') 
exec('sim_trace uec=1-2 protocol=rrc on') 
exec('sim_trace uec=1-2 protocol=nr_rrc on') 
exec('sim_trace amf=1-2 protocol=ng on') 
exec('cfg_end') 

exec('set_log log_to_file=on') 
exec('sim_start version_check=off') 